  function press(a) { if (!held[a]) edge[a] = true; held[a] = true; ensureAudio(); }
  function release(a) { held[a] = false; }
  window.addEventListener('keydown', function (e) {
    if (e.code === 'KeyO') {
      showDebugOverlay = !showDebugOverlay;
      say(showDebugOverlay ? 'DEBUG OVERLAY ON' : 'DEBUG OVERLAY OFF', 1.0);
    }
    if (DEBUG || showDebugOverlay) {
      if (e.code === 'KeyK') {
        if (state === 'play') {
          if (boss && !boss.dead) {
            damageEnemy(boss, 999, 1);
            say('DEBUG: WARDEN KILLED', 1.0);
          } else if (!boss2) {
            window.__GAME.triggerResurrection();
            say('DEBUG: RESURRECTION TRIGGERED', 1.0);
          }
        }
      }
      if (e.code === 'KeyP') {
        if (boss2 && !boss2.dead) {
          damageEnemy(boss2, 999, 1);
          say('DEBUG: SKELETON KING KILLED', 1.0);
        }
      }
      if (e.code === 'KeyB') {
        if (player && !player.dead) {
          player.shieldCharge = 6;
          player.shieldHp = 0;
          triggerHeroShieldBreak(player);
          say('DEBUG: SHIELD SHATTERED → SHOCKWAVE', 1.2);
        }
      }
    }
    if (/^Digit[1-4]$/.test(e.code) && boss2) {
      boss2.debugPhase(+e.code[5]);
    }
    var a = KEYMAP[e.code];
    if (!a) return;
    e.preventDefault();
    if (e.repeat) return;
    press(a);
  });
  window.addEventListener('keyup', function (e) {
    var a = KEYMAP[e.code];
    if (a) release(a);
  });
  window.addEventListener('blur', function () { held = {}; });
  cv.addEventListener('pointerdown', function () { cv.focus(); press('start'); });
  cv.addEventListener('pointerup', function () { release('start'); });

  var touchBtns = document.querySelectorAll('#touch button');
  Array.prototype.forEach.call(touchBtns, function (b) {
    var a = b.getAttribute('data-act');
    b.addEventListener('pointerdown', function (e) {
      e.preventDefault();
      try { b.setPointerCapture(e.pointerId); } catch (x) {}
      b.classList.add('on'); press(a);
    });
    var up = function () { b.classList.remove('on'); release(a); };
    b.addEventListener('pointerup', up);
    b.addEventListener('pointercancel', up);
    b.addEventListener('lostpointercapture', up);
  });

